SELECT l.id AS lead_id, l.title, l.extracted, p.sector, p.needs AS domain_needs
FROM leads l LEFT JOIN LATERAL (SELECT * FROM prospects pr WHERE pr.lead_id=l.id ORDER BY pr.created_at DESC LIMIT 1) p ON true
WHERE l.id=$1::uuid AND l.status='researched' LIMIT 1;

