const lead = $json;
const reqs = Array.isArray(lead.extracted?.requirements) ? lead.extracted.requirements : [];
const queries = reqs.map(r => typeof r === 'string' ? r : String(r.label ?? r.text ?? r.description ?? '')).map(s => s.trim()).filter(Boolean);
return [{ json: { lead_id: lead.lead_id, title: lead.title, sector: lead.sector, queries: queries.length ? queries : [String(lead.title ?? 'tender')] } }];

const src = $('Build Requirement Queries').first().json;
const bundles = [
  ['cv', $items('Qdrant Search — CVS')],
  ['project', $items('Qdrant Search — PROJECTS')],
  ['stack', $items('Qdrant Search — EXPERTISE')],
];
const byDocument = new Map();
for (const [assetType, items] of bundles) {
  for (const item of items) {
    for (const point of (item.json.result?.points ?? [])) {
      const payload = point.payload ?? {};
      if (payload.source !== 'supabase_storage' || !payload.document_id || !payload.source_path || !payload.source_bucket) continue;
      const key = assetType + ':' + payload.document_id;
      const score = Math.round(Number(point.score ?? 0) * 100);
      if (!byDocument.has(key) || score > byDocument.get(key).score) byDocument.set(key, { lead_id: src.lead_id, asset_type: assetType, asset_ref: payload.document_id, payload, score });
    }
  }
}
const matches = [...byDocument.values()].sort((a, b) => b.score - a.score).slice(0, 30);
return [{ json: { matches_json: JSON.stringify({ matches }) } }];

const src = $json ?? {};
let leadId = '';
try { leadId = $('Resolve Lead Id').first().json.lead_id; } catch (e) {}
if (!leadId) { try { leadId = src.lead_id ?? src.id ?? ''; } catch (e) {} }
const errRaw = src.error ?? src.message ?? src;
const errText = typeof errRaw === 'string' ? errRaw : (errRaw.message ?? JSON.stringify(errRaw));
return [{ json: { error_json: JSON.stringify({ lead_id: String(leadId ?? ''), error: String(errText).slice(0, 500) }) } }];
